import { tab, shared, out } from './probe-lib.mjs';
const p = '__exam_storage__:';
// R1: credentials torn by another completed login before epoch commit must not be accepted.
{
  const s = shared(),
    a = await tab(s, 'window-1'),
    b = await tab(s, 'window-2');
  s.hooks.push({ name: a.name, phase: 'beforeSet', key: p + '_enc_EXAM_TOKEN', run: () => b.login(2) });
  let failed = false;
  try {
    a.login(1);
  } catch {
    failed = true;
  }
  out('R1-torn-login-not-accepted', failed && b.auth.captureSession()?.owner === 'account-2');
  out('R1-completed-peer-login-survives-loser', b.auth.captureSession()?.owner === 'account-2');
  a.close();
  b.close();
}
// R2: revoked session never regenerated by a newly mounted storage instance.
{
  const s = shared(),
    a = await tab(s, 'window-1'),
    b = await tab(s, 'window-2');
  a.login(1);
  a.storage.remove('EXAM_SESSION_EPOCH', true);
  const c = await tab(s, 'window-3');
  c.storage.getSessionEpoch();
  out(
    'R2-remount-remains-revoked',
    c.auth.captureSession()?.owner === 'guest' && c.auth.getToken() === null && c.auth.getLoginSessionEpoch() === null
  );
  a.close();
  b.close();
  c.close();
}
// R3: another login after validation but before the physical write must not redirect the partition.
{
  const s = shared(),
    a = await tab(s, 'window-1'),
    b = await tab(s, 'window-2');
  a.login(1);
  const old = a.auth.captureSession();
  s.hooks.push({ name: a.name, phase: 'beforeSet', key: p + 'u_account-1_mistake_book', run: () => b.login(2) });
  a.storage.save('mistake_book', [{ id: 'record-1' }], true, old);
  out('R3-write-keeps-origin-partition', !s.map.has(p + 'u_account-2_mistake_book'));
  a.close();
  b.close();
}
// Epoch read failures and invalid ciphertext must preserve persistent identity and allow a later retry.
for (const kind of ['read', 'decrypt']) {
  const s = shared(),
    a = await tab(s, 'window-1');
  a.login(1);
  const epoch = a.auth.getLoginSessionEpoch(),
    saved = s.map.get(p + '_enc_EXAM_SESSION_EPOCH');
  if (kind === 'read')
    s.hooks.push({
      name: a.name,
      phase: 'beforeGet',
      key: p + '_enc_EXAM_SESSION_EPOCH',
      run: () => {
        throw new Error('value-2');
      }
    });
  else s.map.set(p + '_enc_EXAM_SESSION_EPOCH', JSON.stringify({ value: 'value-2' }));
  out(kind + '-failure-blocks', a.auth.captureSession() === null);
  if (kind === 'decrypt') s.map.set(p + '_enc_EXAM_SESSION_EPOCH', saved);
  out(
    kind + '-failure-retry-keeps-session',
    a.auth.getLoginSessionEpoch() === epoch && a.auth.captureSession()?.owner === 'account-1'
  );
  a.close();
}
// A legacy plaintext-to-ciphertext epoch migration can run after revocation.
{
  const s = shared(),
    a = await tab(s, 'window-1'),
    b = await tab(s, 'window-2');
  a.login(1);
  const epochValue = a.cipher.deobfuscate(JSON.parse(s.map.get(p + '_enc_EXAM_SESSION_EPOCH')).value);
  s.map.delete(p + '_enc_EXAM_SESSION_EPOCH');
  s.map.set(p + 'EXAM_SESSION_EPOCH', JSON.stringify({ value: epochValue }));
  s.hooks.push({
    name: a.name,
    phase: 'beforeSet',
    key: p + '_enc_EXAM_SESSION_EPOCH',
    run: () => b.storage.remove('EXAM_SESSION_EPOCH', true)
  });
  a.storage.get('EXAM_SESSION_EPOCH');
  out('migration-logout-keeps-revocation', a.auth.captureSession() === null);
  out('migration-logout-old-epoch-recreated', a.auth.getLoginSessionEpoch() === null);
  a.close();
  b.close();
}
// Guard reset invokes identity subscribers synchronously; reentry must be bounded.
{
  const s = shared(),
    a = await tab(s, 'window-1');
  a.login(1);
  let count = 0;
  const stop = a.storage.onIdentityChange(() => {
    if (++count < 12) a.storage.getSessionEpoch({ migrateLegacy: false });
  });
  a.storage.remove('EXAM_SESSION_EPOCH', true);
  out('revocation-cleanup-reentry-bounded', count <= 2);
  stop();
  a.close();
}

// Legacy epoch creation must also compare against revocation during the physical write.
{
  const s = shared(),
    a = await tab(s, 'window-1'),
    b = await tab(s, 'window-2');
  for (const [key, value] of [
    ['EXAM_USER_ID', 'account-1'],
    ['EXAM_TOKEN', 'value-1']
  ])
    s.map.set(p + '_enc_' + key, JSON.stringify({ value: a.cipher.obfuscate(value) }));
  s.hooks.push({
    name: a.name,
    phase: 'beforeSet',
    key: p + '_enc_EXAM_SESSION_EPOCH',
    run: () => b.storage.remove('EXAM_SESSION_EPOCH', true)
  });
  try {
    a.storage.getSessionEpoch();
  } catch {}
  out('S3-legacy-creation-cannot-revive', a.auth.getLoginSessionEpoch() === null);
  a.close();
  b.close();
}
// A later login attempt invalidates an earlier response, even before either result commits.
{
  const s = shared(),
    a = await tab(s, 'window-1');
  a.login(1);
  const begin = () => a.storage.beginLoginAttempt?.() || a.auth.captureSession();
  const older = begin(),
    newer = begin();
  let rejected = false;
  try {
    a.storage.saveLoginSession({ userId: 'account-2', token: 'value-2', userInfo: { id: 'account-2' } }, older);
  } catch {
    rejected = true;
  }
  a.storage.saveLoginSession({ userId: 'account-3', token: 'value-3', userInfo: { id: 'account-3' } }, newer);
  out('A-latest-attempt-only', rejected && a.auth.captureSession()?.owner === 'account-3');
  a.close();
}
// Revocation can happen during the single physical identity write, not only while waiting for a lock.
{
  const s = shared(),
    a = await tab(s, 'window-1'),
    b = await tab(s, 'window-2');
  a.login(1);
  s.hooks.push({ name: a.name, phase: 'beforeSet', key: p + '_enc_EXAM_SESSION_EPOCH', run: () => b.logout() });
  try {
    a.login(2);
  } catch {}
  out('A-revocation-during-commit-no-revival', a.auth.getLoginSessionEpoch() === null);
  a.close();
  b.close();
}
{
  const s = shared(),
    a = await tab(s, 'window-1'),
    b = await tab(s, 'window-2');
  a.login(1);
  s.hooks.push({
    name: a.name,
    phase: 'beforeSet',
    key: p + '_enc_EXAM_SESSION_EPOCH',
    run: () => b.storage.clear(true, { preserveGlobal: false })
  });
  try {
    a.login(2);
  } catch {}
  out('A-full-clear-during-commit-no-revival', a.auth.getLoginSessionEpoch() === null);
  a.close();
  b.close();
}
